# step_03: redo closure search considering interactions in either direction between group nodes and shared contact x
nodes = {229,338,378,403,529,543,646,706,728,737,786,843}
start, end = 18400, 35952
ev = [(u,v,t) for (u,v,t) in events if start <= t <= end]
from collections import defaultdict
pair_times = defaultdict(list)
contacts_with = defaultdict(list) # x -> list of (node_in_group, t)
for (u,v,t) in ev:
    pair_times[(u,v)].append(t)
    # if u in group and interacted with v, record v as contact
    if u in nodes:
        contacts_with[v].append((u,t))
    # if v in group and u interacted with v, record u as contact too (interaction where group node is target)
    if v in nodes:
        contacts_with[u].append((v,t))

import itertools
closures = []
for x,lst in contacts_with.items():
    # consider two distinct group members
    for (a,t1),(b,t2) in itertools.permutations(lst,2):
        if a==b: continue
        t_shared = max(t1,t2)
        # look for a<->b event in window
        found = []
        for t3 in pair_times.get((a,b),[]) + pair_times.get((b,a),[]):
            if t_shared <= t3 <= t_shared+800:
                found.append(t3)
        if found:
            closures.append({"a":a,"b":b,"x":x,"t1":t1,"t2":t2,"t_shared":t_shared,"t_close":min(found)})

closures.sort(key=lambda c:c['t_close'])
print('num closures found:', len(closures))
for c in closures:
    print(c)
if closures:
    print('last closing time:', max(c['t_close'] for c in closures))
else:
    print('no closures')
